'use strict';
// Lane-04 QA wrapper: package the already verified lane-03 rope records as
// single-record clips fixtures for the canonical immutable integration builder.
// No animation values are decoded, changed, or regenerated by this script.
const fs = require('fs');
const path = require('path');
const L = require('../../lib/integration.js');

const LANE = __dirname;
const BASE = 'C:/nt100-codebasemain';
const INTEGRATION = path.join(BASE, 'animation/workflows/dolph-ziggler-1-2k19/outputs/dolph-ziggler-1-2k19/parallel-integration');
const BASELINE_CAK = path.join(BASE, '.local/test557-playback-20261017-1907/rollback/aurora-2k25-replace-mod.cak');
const BASELINE_STAGE = path.join(INTEGRATION, 'builds/p14002-pairfix-v2/staging/Animation/CaeAdvanced');
const LANE03 = path.join(INTEGRATION, 'work-order-20261020/lane-03-ropes');
const SOURCE_MANIFEST = path.join(LANE03, 'rope-only-manifest.json');
const SOURCE_VERIFICATION = path.join(LANE03, 'verification.json');
const LINK_VERIFICATION = path.join(LANE03, 'link-verification.json');
const SOURCE_OVERLAY = path.join(LANE03, 'overlays/1314002.clips');
const COMPONENTS_BASE = path.join(INTEGRATION, 'components.json');
const FIXTURE_DIR = path.join(LANE, 'component-overlays');
const FIXTURE_REPORT = path.join(LANE, 'rope-overlay-fixtures.json');
const BUILD_MANIFEST = path.join(LANE, 'components.rope-only.json');
const EXPECTED_BASE = '0FAEAD25F8033225E1479AF07A49EF6CAD65C16945C3AB2EEEC40DE9B6E6D0A1';
const EXPECTED_PHASE_BASE = 'D043FAAC51EC846336A25A9DD0DF34BD631F24069AB00167077463C3B63AA3F5';
const SWAPS = [
  { index: 0, name: 'rope-r15', id: '0x0CC72078B2C27772', fixture: 'p130-rope-r15.clips', sourceChild: 5 },
  { index: 6, name: 'rope-r14', id: '0x0CC72178B2C27925', fixture: 'p130-rope-r14.clips', sourceChild: 4 },
];

function fail(message) { throw new Error(message); }
function hashFile(file) { return L.sha256(fs.readFileSync(file)); }
function idHex(id) { return '0x' + BigInt(id).toString(16).toUpperCase().padStart(16, '0'); }
function trackHexes(record) { return record.trackIdentifiers.map((id) => BigInt(id).toString(16).toUpperCase().padStart(16, '0')); }
function recordBytes(buffer, record) { return buffer.subarray(record.offset, record.offset + record.length); }

function main() {
  const baselineHash = hashFile(BASELINE_CAK).toUpperCase();
  if (baselineHash !== EXPECTED_BASE) fail('owner-played 0FAE base hash mismatch: ' + baselineHash);
  const laneManifest = L.readJson(SOURCE_MANIFEST);
  const laneVerification = L.readJson(SOURCE_VERIFICATION);
  const laneLinkVerification = L.readJson(LINK_VERIFICATION);
  if (laneManifest.baseCak.sha256.toUpperCase() !== EXPECTED_BASE) fail('lane-03 manifest base pin mismatch');
  if (laneVerification.pass !== true || laneVerification.components.length !== 2 || laneVerification.failureReasons.length !== 0) fail('lane-03 source verifier did not pass exactly two rope components');
  if (laneLinkVerification.pass !== true) fail('lane-03 ADefs link verifier did not pass');
  if (JSON.stringify(laneManifest.scope.records) !== JSON.stringify(['14002_15_r14', '14002_15_r15']) || JSON.stringify(laneManifest.scope.excluded) !== JSON.stringify([3])) fail('lane-03 scope is not r14/r15-only with child 3 excluded');
  const sourcePhase = laneManifest.overlay.phaseFiles.find((row) => row.outputFile.endsWith('1314002.clips'));
  if (!sourcePhase || sourcePhase.baseSha256.toUpperCase() !== EXPECTED_PHASE_BASE) fail('lane-03 phase-130 base hash mismatch');
  if (hashFile(SOURCE_OVERLAY).toUpperCase() !== sourcePhase.outputSha256.toUpperCase()) fail('lane-03 verified phase overlay hash mismatch');

  const overlayBuffer = fs.readFileSync(SOURCE_OVERLAY);
  const basePath = path.join(BASELINE_STAGE, '1314002.clips');
  const baseBuffer = fs.readFileSync(basePath);
  if (hashFile(basePath).toUpperCase() !== EXPECTED_PHASE_BASE) fail('0FAE phase-130 clips hash mismatch');
  const overlayClips = L.parseClips(overlayBuffer);
  const baseClips = L.parseClips(baseBuffer);
  if (overlayClips.records.length !== 7 || baseClips.records.length !== 7) fail('phase-130 record count changed');
  const swapped = new Set(SWAPS.map((row) => row.index));
  const phaseRecordChecks = [];
  for (let index = 0; index < baseClips.records.length; index += 1) {
    const before = baseClips.records[index];
    const after = overlayClips.records[index];
    const sameId = BigInt(before.id) === BigInt(after.id);
    const sameTracks = before.trackIdentifiers.length === after.trackIdentifiers.length && trackHexes(before).every((id, slot) => id === trackHexes(after)[slot]);
    const sameFrames = before.frameValue === after.frameValue;
    const exactBytes = recordBytes(baseBuffer, before).equals(recordBytes(overlayBuffer, after));
    if (!sameId || !sameTracks || !sameFrames) fail('phase-130 record identity/track/frame mismatch at index ' + index);
    if (!swapped.has(index) && !exactBytes) fail('lane-03 overlay changed non-rope record index ' + index);
    phaseRecordChecks.push({ index, recordId: idHex(before.id), trackCount: before.trackIdentifiers.length, trackIds: trackHexes(before), frames: before.frameValue, exactBytesVs0FAE: exactBytes, selectedRopeSwap: swapped.has(index) });
  }

  fs.mkdirSync(FIXTURE_DIR, { recursive: true });
  const fixtureRows = [];
  for (const swap of SWAPS) {
    const sourceRecord = overlayClips.records[swap.index];
    if (idHex(sourceRecord.id) !== swap.id) fail(swap.name + ' record ID mismatch at selected index');
    const selected = recordBytes(overlayBuffer, sourceRecord);
    const fixtureBytes = L.buildClips([Buffer.from(selected)]);
    const fixturePath = path.join(FIXTURE_DIR, swap.fixture);
    fs.writeFileSync(fixturePath, fixtureBytes);
    const fixtureLayout = L.parseClips(fixtureBytes);
    if (fixtureLayout.records.length !== 1) fail(swap.name + ' fixture is not single-record');
    const fixtureRecord = fixtureLayout.records[0];
    const fixtureRecordBytes = recordBytes(fixtureBytes, fixtureRecord);
    if (!fixtureRecordBytes.equals(selected)) fail(swap.name + ' wrapper changed complete source record bytes');
    fixtureRows.push({
      component: swap.name,
      sourceChild: swap.sourceChild,
      phase: 130,
      sourceOverlayIndex: swap.index,
      recordId: idHex(fixtureRecord.id),
      frameValue: fixtureRecord.frameValue,
      trackIds: trackHexes(fixtureRecord),
      completeRecordBytes: fixtureRecord.length,
      completeRecordSha256: L.sha256(fixtureRecordBytes),
      fixturePath,
      fixtureBytes: fixtureBytes.length,
      fixtureSha256: L.sha256(fixtureBytes),
    });
  }

  const components = L.readJson(COMPONENTS_BASE);
  if (components.build.source273.sha256.toUpperCase() !== '4F840F174CE7CA11511EF2840F979E19D44CD13E68E5416FB0FF8027033524F1') fail('base integration manifest source-273 pin mismatch');
  const p130 = components.phases.find((phase) => phase.phase === 130);
  if (!p130) fail('base integration manifest has no phase 130');
  p130.overlays.push(
    {
      component: 'rope-r15', status: 'converted-source273-rope',
      provenance: 'Lane-03 verified source child 5; exact record bytes selected from its verified 0FAE-derived phase-130 overlay; no ring-mat overlay.',
      path: fixtureRows.find((row) => row.component === 'rope-r15').fixturePath,
      sha256: fixtureRows.find((row) => row.component === 'rope-r15').fixtureSha256,
    },
    {
      component: 'rope-r14', status: 'converted-source273-rope',
      provenance: 'Lane-03 verified source child 4; exact record bytes selected from its verified 0FAE-derived phase-130 overlay; no ring-mat overlay.',
      path: fixtureRows.find((row) => row.component === 'rope-r14').fixturePath,
      sha256: fixtureRows.find((row) => row.component === 'rope-r14').fixtureSha256,
    },
  );
  if (components.phases.some((phase) => phase.overlays.some((overlay) => /ringmat|o2755/i.test(overlay.component)))) fail('base components unexpectedly contain a ring-mat overlay');
  components.lane = 'parallel-integration-lane04-source273-ropes-only';
  components.generated = new Date().toISOString();
  fs.writeFileSync(BUILD_MANIFEST, JSON.stringify(components, null, 2) + '\n', 'utf8');

  const report = {
    schema: 'aurora-forge/lane04-rope-fixture-preparation/v1',
    baselineCakSha256: baselineHash,
    lane03PhaseOverlaySha256: sourcePhase.outputSha256,
    phase130BaseSha256: EXPECTED_PHASE_BASE,
    phaseRecordChecks,
    selectedSwaps: fixtureRows,
    ringmatRecordIndex5ExactTo0FAE: phaseRecordChecks[5].exactBytesVs0FAE,
    p140OverlayAdded: false,
    c619OrC848RingmatInputsUsed: false,
    buildManifest: BUILD_MANIFEST,
    buildManifestSha256: L.sha256(fs.readFileSync(BUILD_MANIFEST)),
  };
  fs.writeFileSync(FIXTURE_REPORT, JSON.stringify(report, null, 2) + '\n', 'utf8');
  console.log(JSON.stringify({ pass: true, baselineCakSha256: baselineHash, fixtures: fixtureRows.map(({ component, recordId, fixtureSha256, completeRecordSha256 }) => ({ component, recordId, fixtureSha256, completeRecordSha256 })), ringmatRecordIndex5ExactTo0FAE: report.ringmatRecordIndex5ExactTo0FAE, buildManifest: BUILD_MANIFEST, buildManifestSha256: report.buildManifestSha256 }, null, 2));
}

main();
